package com.bank.portal.web; import com.bank.portal.service.BankingService; import com.bank.portal.web.ApiDtos.*; import java.time.YearMonth; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/statements") @RequiredArgsConstructor public class StatementController {private final BankingService service;@PostMapping("/card/{cardId}") public StatementView generate(@PathVariable Long cardId,@RequestParam String month,Authentication a){boolean staff=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_STAFF"));return service.statement(cardId,YearMonth.parse(month),a.getName(),staff);}@GetMapping("/mine") @PreAuthorize("hasRole('CUSTOMER')") public List<StatementView> mine(Authentication a){return service.ownStatements(a.getName());}}
